styles.body:
/* Base IMIS v1.0.0 */

/* @title <3 */
[year_extracted < 3][year_extracted is Not Null] {
	fill: #1a9641;
  	label: [bin];
}

/* @title 3 - 5  */
[year_extracted >= 3] [year_extracted < 5][year_extracted is Not Null] {
	fill: #a6d96a;
  	label: [bin];
}

/* @title 5 - 10 */
[year_extracted >= 5] [year_extracted < 10][year_extracted is Not Null] {
	fill: #fdae61;
  	label: [bin];
}

/* @title 10+ */
[year_extracted >= 10][year_extracted is Not Null] {
	fill: #d7191c;
  	label: [bin];
}

/* @title Unknown */
[year_extracted is null] {
   fill: symbol('shape://times');
   stroke: black;
   stroke-opacity: 0.4;
   label: [bin];
}


* {
	fill-opacity: 0.4;
	stroke: lightgrey;
  	font-fill: #000000;
}

