styles.body:
/* Base IMIS v1.00 */

/* @title Associated Buildings */
[building_associated_to is not null] [building_associated_to <> ''] {
	fill: #FF0000;
  	label: [bin];
}

/* @title Main Buildings */
[building_associated_to is null] {
   fill: #6fa8dc;
   stroke: black;
  label: [bin];
}
:fill {
  stroke: gray;
}

* {
	fill-opacity: 0.4;
  	stroke: #000001;
  	stroke-width: 0.01;
  	stroke-opacity: 0.4;
  	stroke-linejoin: bevel;
}

