styles.body:
/* Base IMIS v1.0.0 */

* {
  	fill: #febfff;
	fill-opacity: 0.4;
  	stroke: #000001;
  	stroke-width: 0.01;
  	stroke-opacity: 0.4;
  	stroke-linejoin: bevel;
}

